// The Webhook node output wraps the request as { headers, params, query, body }.
const body = $input.first().json.body ?? {};

const errors = [];

// ── name ────────────────────────────────────────────────
if (typeof body.name !== 'string' || body.name.trim().length === 0) {
  errors.push('name is required');
} else if (body.name.length > 200) {
  errors.push('name must be at most 200 characters');
}

// ── email ───────────────────────────────────────────────
if (typeof body.email !== 'string' || body.email.trim().length === 0) {
  errors.push('email is required');
} else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(body.email)) {
  errors.push('email is not valid');
}

// ── message ─────────────────────────────────────────────
if (typeof body.message !== 'string' || body.message.trim().length === 0) {
  errors.push('message is required');
} else if (body.message.length > 5000) {
  errors.push('message must be at most 5000 characters');
}

// ── source ──────────────────────────────────────────────
const allowedSources = ['website', 'email', 'form', 'api', 'other'];
const source = typeof body.source === 'string' && body.source.length > 0
  ? body.source
  : 'website';
if (!allowedSources.includes(source)) {
  errors.push(`source must be one of: ${allowedSources.join(', ')}`);
}

return [{
  json: {
    valid: errors.length === 0,
    errors,
    lead: {
      name: typeof body.name === 'string' ? body.name.trim() : '',
      email: typeof body.email === 'string' ? body.email.trim().toLowerCase() : '',
      company: typeof body.company === 'string' && body.company.trim().length > 0
        ? body.company.trim()
        : null,
      message: typeof body.message === 'string' ? body.message.trim() : '',
      source,
    },
  },
}];

