const response = $input.first().json;
const raw = response?.message?.content;

if (typeof raw !== 'string' || raw.length === 0) {
  throw new Error('Ollama returned no content');
}

let ai;
try {
  ai = JSON.parse(raw);
} catch (e) {
  throw new Error('Ollama returned invalid JSON: ' + raw.slice(0, 300));
}

// Pull the original lead from the Create Lead node.
const lead = $('Create Lead').item.json;

return [{
  json: {
    lead,
    ai: {
      summary: ai.summary,
      category: ai.category,
      budget_usd: ai.budget_usd ?? null,
      urgency: ai.urgency,
    },
    model: 'llama3.2',
  },
}];
